// src/parser/code-mask.ts
function maskCodeRegions(text) {
  if (!text || text.indexOf("\`") === -1 && text.indexOf("~~~") === -1) {
    return text;
  }
  const chars = text.split("");
  const n = text.length;
  const blank = (from, to) => {
    const end = Math.min(to, n);
    for (let k = from; k < end; k++)
      chars[k] = " ";
  };
  let i = 0;
  while (i < n) {
    const atLineStart = i === 0 || text[i - 1] === "\\n";
    if (atLineStart) {
      const fence = fenceEnd(text, i);
      if (fence !== null) {
        blank(i, fence);
        i = fence;
        continue;
      }
    }
    if (text[i] === "\`") {
      let run = 0;
      while (i + run < n && text[i + run] === "\`")
        run++;
      const close = findBacktickRun(text, i + run, run);
      if (close !== -1) {
        const end = close + run;
        blank(i, end);
        i = end;
        continue;
      }
      i += run;
      continue;
    }
    i++;
  }
  return chars.join("");
}
function fenceEnd(text, at) {
  let j = at;
  while (j < text.length && (text[j] === " " || text[j] === "	"))
    j++;
  const ch = text[j];
  if (ch !== "\`" && ch !== "~")
    return null;
  let markers = 0;
  while (text[j + markers] === ch)
    markers++;
  if (markers < 3)
    return null;
  let pos = text.indexOf("\\n", j);
  pos = pos === -1 ? text.length : pos + 1;
  while (pos < text.length) {
    let k = pos;
    while (k < text.length && (text[k] === " " || text[k] === "	"))
      k++;
    if (text[k] === ch) {
      let run = 0;
      while (text[k + run] === ch)
        run++;
      if (run >= markers) {
        let e = k + run;
        while (e < text.length && (text[e] === " " || text[e] === "	"))
          e++;
        if (e >= text.length || text[e] === "\\n") {
          return e < text.length ? e + 1 : text.length;
        }
      }
    }
    const next = text.indexOf("\\n", pos);
    if (next === -1)
      break;
    pos = next + 1;
  }
  return text.length;
}
function findBacktickRun(text, from, runLen) {
  let j = from;
  while (j < text.length) {
    if (text[j] === "\`") {
      let run = 0;
      while (text[j + run] === "\`")
        run++;
      if (run === runLen)
        return j;
      j += run;
    } else {
      j++;
    }
  }
  return -1;
}

// src/parser/compound.ts
function mergeCompoundCitations(text) {
  const ADJACENT = /\\[([^\\]\\n]*@[^\\]\\n]*)\\]([ \\t]*\\n?[ \\t]*)\\[([^\\]\\n]*@[^\\]\\n]*)\\]/g;
  let prev;
  let out = text;
  do {
    prev = out;
    out = out.replace(ADJACENT, "[$1; $3]");
  } while (out !== prev);
  return out;
}

